TEST_F(TransFlowTest, CompositeTrans) {
	auto videoClip = addClip_test(mov, true, 2);
	ASSERT_NE(videoClip, nullptr);
	auto compositeClip = CheckCompositeTimelinePerview(videoClip->GetTLBegin(), videoClip->GetTLEnd(), true, true);
	ASSERT_NE(compositeClip, nullptr);
	unsigned int timelineCnt = 0xffff;
	EXPECT_EQ(Success, pEditing->GetTimelineCount(timelineCnt));
	EXPECT_EQ(Success, pEditing->SwitchTimeline(timelineCnt - 1));
	auto postVideoClip = base_utils::AddClip(pEditing, mp4video, tlb::CLIP_TYPE_VIDEO, tlb::TRACK_TYPE_VIDEO, false, compositeClip->GetTLEnd() - compositeClip->GetTLBegin());
	string transPath = trans_path + "2_Box_Flip_2/Data/data.xml";
	string transPath2 = trans_path + "2_Erase/Data/data.xml";
	string transPath3 = trans_path + "2_Phantom_parallax_zoom_up_298692/Data/data.xml";
	SetTransToClip("post", pObj->CreateTransitionClipByPath(transPath.c_str()), postVideoClip, 20000000, false);
	SetTransToClip("post_pre", pObj->CreateTransitionClipByPath(transPath2.c_str()), compositeClip, 20000000, true);
	SetTransToClip("pre", pObj->CreateTransitionClipByPath(transPath3.c_str()), compositeClip, 20000000, true);

	auto preview = pTlb->CreateTlbPreview();
	PreviewWindow* window = initWindow(preview, 1920, 1080, "复合时间线和clip转场");
	vector<int64_t> positions{ 13000000, 37000000, 46000000 };
	vector<IMAGE_TYPE> dumplist;
	EXPECT_TRUE(dumpPreview(TRANS_SHOT, "CompositeTrans", positions, preview, dumplist));
	EXPECT_TRUE(cmpPics(cmppath, dumplist)) << dump_utils::SaveProject( TRANS_SHOT, "CompositeTrans.wesproj");
	Play(preview, pTlb, window);
}...
```

